def render_section(title, subtitle, image_uri, theme=""):
    # Ogni sezione conserva la grafica standard, con palette dedicate per 2 e 3.
    css_class = "nr-section" + (" nr-section-" + theme if theme else "")
    st.markdown(f"""
    <div class="{css_class}">
      <img src="{image_uri}" alt="">
      <div><div class="nr-section-title">{title}</div>
      <div class="nr-section-sub">{subtitle}</div></div>
    </div>""", unsafe_allow_html=True)

def render_separator_visual(image_uri, alt_text=""):
    st.markdown(f"""
    <div class="nr-separator-visual">
      <img src="{image_uri}" alt="{alt_text}">
    </div>""", unsafe_allow_html=True)


def _fmt_count(value):
    try:
        return f"{int(value):,}".replace(",", ".")
    except (TypeError, ValueError):
        return "0"


def _fmt_price(value):
    try:
        amount = float(value)
        if not pd.notna(amount):
            return "0"
        if amount.is_integer():
            return _fmt_count(int(amount))
        return f"{amount:,.2f}".replace(",", "¤").replace(".", ",").replace("¤", ".")
    except (TypeError, ValueError):
        return "0"


def render_mobile_sales_table(df, sede):
    # All source fields and their values remain unchanged; only view labels differ.
    palette = "nr-pink" if sede == "SANTACRUZ" else "nr-green"
    headers = ["N.", "Fecha", "Cliente", "Categoría", "Q.", "Precio<br>Tot"]
    colclasses = ["nr-col-nota", "nr-col-fecha", "nr-col-cliente",
                  "nr-col-categoria", "nr-col-cant", "nr-col-precio"]
    rows = []
    for _, item in df.iterrows():
        fecha = item.get("Fecha")
        if pd.notna(fecha):
            date_text = f'<span>{fecha:%d/%m}</span><span>{fecha:%Y}</span>'
        else:
            date_text = "—"
        cat = str(item.get("Categoría") or "")
