# ACCESSO VISITATORE: password al primo avvio, cookie firmato per 180 giorni.
# Nessuna password, chiave Supabase o token permanente viene inserito nel codice.
# Le sessioni restano valide soltanto sul medesimo browser/dispositivo.
COOKIE_NAME = "deposito56_mobile_access_v1"
COOKIE_DAYS = 180


def _auth_signing_key(password: str) -> bytes:
    # La chiave privata Supabase esiste già in Secrets. Usata solo sul server.
    private_key = secret_value("supabase", "secret_key")
    if not private_key:
        st.error("Falta configurar Supabase en Secrets.")
        st.stop()
    return hashlib.sha256(("deposito56:session:v1:" + password + ":" + private_key).encode("utf-8")).digest()


def _make_auth_cookie(password: str) -> str:
    payload = {
        "exp": int((datetime.now(timezone.utc) + timedelta(days=COOKIE_DAYS)).timestamp()),
        "kind": "deposito56_visitante",
    }
    body = base64.urlsafe_b64encode(json.dumps(payload, separators=(",", ":")).encode()).decode().rstrip("=")
    signature = hmac.new(_auth_signing_key(password), body.encode("ascii"), hashlib.sha256).hexdigest()
    return f"{body}.{signature}"


def _valid_auth_cookie(cookie: object, password: str) -> bool:
    if not isinstance(cookie, str) or len(cookie) > 4096:
        return False
    try:
        body, signature = cookie.split(".", 1)
        expected = hmac.new(_auth_signing_key(password), body.encode("ascii"), hashlib.sha256).hexdigest()
        if not hmac.compare_digest(signature, expected):
            return False
        data = json.loads(base64.urlsafe_b64decode(body + "=" * (-len(body) % 4)))
        return (data.get("kind") == "deposito56_visitante"
                and isinstance(data.get("exp"), int)
                and int(datetime.now(timezone.utc).timestamp()) < data["exp"])
    except (ValueError, TypeError, KeyError, UnicodeError, json.JSONDecodeError):
        return False


visitor_password = secret_value("visitante", "password")
if not visitor_password:
    st.error("Configura [visitante] password en Secrets de esta aplicación.")
    st.stop()

cookies = CookieController(key="deposito56_cookies_controller")
authorized = st.session_state.get("deposito56_visitante_autorizado", False)
if not authorized:
    authorized = _valid_auth_cookie(cookies.get(COOKIE_NAME), visitor_password)
    if authorized:
        st.session_state["deposito56_visitante_autorizado"] = True

if not authorized:
    render_hero()
