@st.cache_resource
def client(url: str, key: str):
    return create_client(url,key)


def fetch_all(table, fields, location=None):
    result=[]; start=0; n=1000
    api=client(url,key)
    while True:
        query=api.table(table).select(fields)
        if location is not None:
            query=query.eq("sede",location)
        part=query.range(start,start+n-1).execute().data or []
        result.extend(part)
        if len(part)<n: break
        start+=n
    return result


@st.cache_data(ttl=60, show_spinner="Consultando datos actualizados...")
def load_data():
    sales=fetch_all("ventas", "id,sede,nro_nota,fecha,cliente,categoria,descripcion,cantidad,precio_unitario,precio_total,precio_dolar")
    try:
        categories=fetch_all("categorias_config", "nombre,visible_stock,orden")
        categories=sorted(categories, key=lambda row: (int(row.get("orden") or 1000), str(row.get("nombre") or "").casefold()))
    except Exception:
        categories=None
    return sales,categories


def render_price_consultation(categories):
    """Prezzi in sola lettura: stesso schema e calcolo del deposito56 PC.

    Prezzi: precios_categorias(categoria,precio_usd)
    Cambio: precios_configuracion(clave='usd_a_bs',valor)
    Bs. = round(precio_usd * cambio, 2) come in PC.
    """
    st.markdown('<div class="nr-precios-title">TABLA DE PRECIOS · NUEVOS RUMBOS</div>',
                unsafe_allow_html=True)
    try:
        existing = fetch_all("precios_categorias", "categoria,precio_usd")
        config = fetch_all("precios_configuracion", "clave,valor")
    except Exception:
        st.error("No se pudieron consultar los precios USD y el cambio desde Supabase. "
                 "Verifica permisos de lectura y configuración de la aplicación móvil.")
        return

    price_index = {
        str(row.get("categoria") or "").strip(): row.get("precio_usd")
        for row in existing
    }
    cambio_raw = next((row.get("valor") for row in config
                       if str(row.get("clave") or "") == "usd_a_bs"), None)
    try:
        cambio = float(cambio_raw) if cambio_raw is not None else 0.0
    except (TypeError, ValueError):
        cambio = 0.0

    # Stesso ordine delle categorie del PC, con un recupero dei prezzi esistenti
    # se la tabella di configurazione non è temporaneamente disponibile.
    # Filtro e Manometro non devono comparire nella TABLA DE PRECIOS:
    # Filtro 12 è la categoria valida e resta visibile. Questa esclusione
    # riguarda solo questa tabella e non modifica il deposito Visitante.
    def _price_category_key(value):
        import unicodedata
        normalized = unicodedata.normalize("NFKD", str(value or ""))
        return "".join(ch for ch in normalized if not unicodedata.combining(ch)).casefold().replace(" ", "").strip()

    excluded_price_categories = {"filtro", "manometro"}
    names = list(dict.fromkeys(
        str(row.get("nombre") or "").strip() for row in (categories or [])
        if str(row.get("nombre") or "").strip()
        and _price_category_key(row.get("nombre")) not in excluded_price_categories
    ))
    if not names:
        names = list(dict.fromkeys(
            name for name in price_index
            if name and _price_category_key(name) not in excluded_price_categories
        ))
    if not names:
        st.warning("No se encontraron categorías ni precios en Supabase.")
        return

    if cambio > 0:
        st.markdown(
            '<div class="nr-precios-cambio">✕ CAMBIO USD → Bs.: '
            + html.escape(_fmt_price(cambio)) + '</div>',
            unsafe_allow_html=True,
        )
    else:
        st.warning("El cambio USD → Bs. no está configurado. "
                   "Se muestran los precios USD; el valor en Bs. queda pendiente.")

    rows=[]
    for name in names:
        raw=price_index.get(name)
        try:
            usd = float(raw) if raw is not None else None
            if usd is not None and not pd.notna(usd):
                usd = None
        except (TypeError, ValueError):
            usd = None
        # Formula idéntica a la versión PC (round de cada resultado individual).
        bs = round(float(usd) * cambio, 2) if usd is not None and cambio > 0 else None
        usd_text = _fmt_price(usd) if usd is not None else "—"
        bs_text = _fmt_price(bs) if bs is not None else "—"
        rows.append(
            '<tr><td>' + html.escape(name) + '</td>'
            '<td class="nr-price-amount">' + html.escape(usd_text) + '</td>'
            '<td class="nr-price-amount">' + html.escape(bs_text) + '</td></tr>'
        )
    st.markdown(
        '<div class="nr-price-grid-wrap"><table class="nr-price-table nr-price-table-three" translate="no">'
        '<thead><tr><th>CATEGORÍA</th><th>USD ($)</th><th>Bs.</th></tr></thead>'
        '<tbody>' + ''.join(rows) + '</tbody></table></div>',
        unsafe_allow_html=True,
    )
    st.caption("Solo consulta. Los precios y el cambio se modifican exclusivamente desde el editor de PC.")
    st.markdown(
        '<div class="nr-qr-wrap"><div class="nr-qr-card">'
        '<h3>MÉTODO DE PAGO QR</h3>'
        f'<img src="{QR_BANCO_UNION_URI}" alt="QR Banco Unión">'
        '<p>Escanea este código para realizar el pago.</p>'
        '</div></div>',
        unsafe_allow_html=True,
    )


