    all_sales=pd.DataFrame(records,columns=["Sede","_sede",*DATA_COLS])

    render_section("1 · NOTAS DE VENTAS — YINES Y LAURA", "Dos tablas de consulta · columnas simplificadas", TITLE_BOX_VECTOR_URI)
    # Contatore settimanale: da lunedì a sabato inclusi, riparte ogni lunedì.
    # Nota: più righe di prodotti con lo stesso numero di nota contano una sola volta.
    oggi_settimana = date.today()
    lunedi_settimana = oggi_settimana - pd.Timedelta(days=oggi_settimana.weekday())
    sabato_settimana = lunedi_settimana + pd.Timedelta(days=5)


    # Excel della settimana precedente: solo esportazione, nessuna modifica ai dati.
    # Creato con il formato XLSX Office Open XML utilizzando soltanto librerie standard.
    _PLANTILLA_NOTAS_EMBEDDED = ''

    def _excel_semana_anterior(df, sede, lunes, sabado):
        """Riproduce la grafica del foglio Excel fornito dall'utente.

        Mantiene titolo fucsia, date, intestazioni verdi, righe alternate,
        tutte le 10 colonne e formula SOMMA TOTALE in fondo alla colonna I.
        Usa la plantilla Excel originale (solo lettura) e moduli standard Python.
        """
        from copy import deepcopy
        from io import BytesIO
        from pathlib import Path
        from zipfile import ZipFile, ZIP_DEFLATED
        from xml.etree import ElementTree as ET
        from datetime import date as _date, datetime as _datetime
        import math

        # Modello Excel incorporato: non causa errori se il file separato manca.
        # Se il file si trova accanto al programma, viene usato come prima.
        from io import BytesIO
        from base64 import b64decode
        template_path = Path(__file__).resolve().with_name('plantilla_notas_semanal.xlsx')
        template_source = template_path if template_path.is_file() else BytesIO(b64decode(_PLANTILLA_NOTAS_EMBEDDED))
        # Preserve Office Open XML namespace aliases declared in the original
        # workbook. Without these aliases, ElementTree rewrites xr/xr2/xr3
        # prefixes to ns1/ns2 while mc:Ignorable still refers to xr/xr2/xr3.
        # Microsoft Excel then rejects the generated file as malformed.
        import re

        def _office_compatible_xml(xml_root, original_bytes):
            original_text = original_bytes.decode('utf-8-sig')
            aliases = dict(re.findall(r'xmlns:([A-Za-z][\w.-]*)=[\"\']([^\"\']+)[\"\']', original_text.split('?>', 1)[-1].split('>', 1)[0]))
            for alias, uri in aliases.items():
                if alias not in ('xml', 'xmlns') and not alias.startswith('ns'):
                    try:
                        ET.register_namespace(alias, uri)
                    except ValueError:
                        pass
            result = ET.tostring(xml_root, encoding='utf-8', xml_declaration=True)
            xml = result.decode('utf-8')
            # Registering aliases alone does not emit unused xmlns declarations.
            # They are nevertheless required by the mc:Ignorable attribute.
            ignorable = re.search(r'\b(?:mc|ns\d+):Ignorable=[\"\']([^\"\']*)[\"\']', xml)
            if ignorable:
                root_end = xml.find('>', xml.find('?>') + 2)
                root_start = xml.find('<', xml.find('?>') + 2)
                root_open = xml[root_start:root_end]
                additional = ''
                for alias in ignorable.group(1).split():
                    if 'xmlns:' + alias + '=' not in root_open and alias in aliases:
                        additional += ' xmlns:' + alias + '=\"' + aliases[alias] + '\"'
                if additional:
                    xml = xml[:root_end] + additional + xml[root_end:]
            return xml.encode('utf-8')

        M = 'http://schemas.openxmlformats.org/spreadsheetml/2006/main'
        ET.register_namespace('', M)
        q = lambda tag: '{' + M + '}' + tag

        def _set_cell(row, address, value, style=None):
            cell = ET.SubElement(row, q('c'), {'r': address})
            if style is not None:
                cell.set('s', str(style))
            if value is None or value == '':
                return
            if isinstance(value, (_date, _datetime)):
                try:
                    value = (value.date() if isinstance(value, _datetime) else value) - _date(1899,12,30)
                    value = value.days
                    cell.set('s', '2')
                except Exception:
                    value = str(value)
            if isinstance(value, (int, float)) and not isinstance(value, bool) and math.isfinite(float(value)):
                ET.SubElement(cell, q('v')).text = str(value)
            else:
                cell.set('t', 'inlineStr')
                i = ET.SubElement(cell, q('is'))
                ET.SubElement(i, q('t')).text = str(value)

        columns = ['Sede', 'Nro Nota', 'Fecha', 'Cliente', 'Categoría',
                   'Descripción', 'Cantidad', 'Precio Unitario (Bs.)',
                   'Precio Total (Bs.)', 'Precio en Dólar']
        raw_data = []
        sede_display = 'Santa Cruz' if sede == 'SANTACRUZ' else 'Tarija'
        for _, item in df.iterrows():
            vals = [sede_display] + [item.get(c) for c in columns[1:]]
            cleaned = []
            for v in vals:
                try:
                    if pd.isna(v):
                        v = None
                except (TypeError, ValueError):
                    pass
                if hasattr(v, 'to_pydatetime'):
                    v = v.to_pydatetime()
                if hasattr(v, 'item') and not isinstance(v, (_date, _datetime)):
                    try: v = v.item()
                    except (TypeError, ValueError): pass
                cleaned.append(v)
            raw_data.append(cleaned)

        with ZipFile(template_source) as z:
            contents = {n: z.read(n) for n in z.namelist()}

        sheet = ET.fromstring(contents['xl/worksheets/sheet1.xml'])
        sheet_data = sheet.find(q('sheetData'))
        originals = {int(row.get('r')): row for row in list(sheet_data)}
        # Keep banner, interval heading, table header (rows 1–4).
        for row in list(sheet_data):
            if int(row.get('r')) >= 5:
                sheet_data.remove(row)

        def _replace_banner(row, title):
            for oldcell in list(row):
                if oldcell.tag == q('c') and oldcell.get('r', '').startswith('A'):
                    row.remove(oldcell)
                    break
            newcell = ET.Element(q('c'), {'r': f'A{row.get("r")}', 's': '5' if row.get('r') == '1' else '6', 't': 'inlineStr'})
            i = ET.SubElement(newcell, q('is'))
            ET.SubElement(i, q('t')).text = title
            row.insert(0, newcell)

        _replace_banner(originals[1], 'NUEVO RUMBOS - NOTAS ' + sede_display.upper())
        _replace_banner(originals[2], f'Rango de fechas: {lunes:%d/%m/%Y} - {sabado:%d/%m/%Y}')

        # Excel table carries alternating row banding. Keep numeric/date formats.
        styles = [None, '1', '2', None, None, None, '1', '3', '3', '4']
        numeric_cols = {1, 2, 6, 7, 8, 9}
        for idx, values in enumerate(raw_data):
            n = idx + 5
            row = deepcopy(originals[5])
            row.set('r', str(n))
            for cell in list(row):
                if cell.tag == q('c'): row.remove(cell)
            for cidx, v in enumerate(values):
                if cidx in numeric_cols and v not in (None, '') and cidx != 2:
                    try: v = float(v) if cidx in (7,8,9) else int(v)
                    except (ValueError, TypeError): pass
                _set_cell(row, f'{chr(65+cidx)}{n}', v, styles[cidx])
            sheet_data.append(row)

        total_row_num = 5 + len(raw_data)
        total_row = deepcopy(originals[20])
        total_row.set('r', str(total_row_num))
        for cell in list(total_row):
            if cell.tag == q('c'): total_row.remove(cell)
        total = ET.SubElement(total_row, q('c'), {'r': f'I{total_row_num}', 's': '3'})
        ET.SubElement(total, q('f')).text = f'SUM(I5:I{total_row_num-1})' if raw_data else 'SUM(I5:I5)'
        total_amount = sum(float(vals[8] or 0) for vals in raw_data)
        ET.SubElement(total, q('v')).text = str(total_amount)
        sheet_data.append(total_row)

        dimension = sheet.find(q('dimension'))
        if dimension is not None: dimension.set('ref', f'A1:J{total_row_num}')
        contents['xl/worksheets/sheet1.xml'] = _office_compatible_xml(sheet, contents['xl/worksheets/sheet1.xml'])

        table = ET.fromstring(contents['xl/tables/table1.xml'])
        table.set('ref', f'A4:J{total_row_num}')
        table.set('name', 'TablaNotasSantaCruz' if sede == 'SANTACRUZ' else 'TablaNotasTarija')
        table.set('displayName', table.get('name'))
        auto_filter = table.find(q('autoFilter'))
        if auto_filter is not None: auto_filter.set('ref', f'A4:J{total_row_num-1}' if raw_data else 'A4:J4')
        contents['xl/tables/table1.xml'] = _office_compatible_xml(table, contents['xl/tables/table1.xml'])

        if 'xl/calcChain.xml' in contents:
            chain = ET.fromstring(contents['xl/calcChain.xml'])
            for cell in chain.findall(q('c')):
                if cell.get('r') == 'I20': cell.set('r', f'I{total_row_num}')
            contents['xl/calcChain.xml'] = ET.tostring(chain, encoding='utf-8', xml_declaration=True)

        # Update sheet tab name, not the workbook's visible design.
        if sede != 'SANTACRUZ':
            workbook_xml = ET.fromstring(contents['xl/workbook.xml'])
            sh = workbook_xml.find(q('sheets'))
            if sh is not None and len(sh): sh[0].set('name', 'Notas Tarija')
            contents['xl/workbook.xml'] = _office_compatible_xml(workbook_xml, contents['xl/workbook.xml'])

        output = BytesIO()
        with ZipFile(output, 'w', ZIP_DEFLATED) as z:
            for name, data in contents.items():
                z.writestr(name, data)
        return output.getvalue()

    for sede, display in SEDES_NOTAS_VISITANTE.items():
        df=all_sales.loc[all_sales["_sede"]==sede,COLUMNAS_NOTAS_VISITANTE].copy().sort_values(["Fecha","Nro Nota"],kind="stable")
        date_note = df["Fecha"].dt.date
        # Esclude la domenica e considera soltanto le note della settimana in corso.
        note_settimana = df.loc[
            (date_note >= lunedi_settimana) &
            (date_note <= sabato_settimana) &
            (date_note <= oggi_settimana)
        ]
        # Il pulsante riepiloga esclusivamente le note e il valore della settimana.
        # Le tabelle sotto continuano a mostrare tutto lo storico senza modifiche.
        conteggio_settimana = int(note_settimana["Nro Nota"].nunique())
        importo_settimana = float(note_settimana["Precio Total (Bs.)"].sum())
        # Importi senza centesimi per la visualizzazione del riepilogo.
        importo_settimana_fmt = f"{importo_settimana:,.0f}".replace(",", ".")

        # Cicli mensili personalizzati: YINES 16→15, LAURA 13→12.
        giorno_inizio = 16 if sede == "SANTACRUZ" else 13
        if oggi_settimana.day >= giorno_inizio:
            anno_inizio, mese_inizio = oggi_settimana.year, oggi_settimana.month
        else:
            anno_inizio = oggi_settimana.year if oggi_settimana.month > 1 else oggi_settimana.year - 1
            mese_inizio = oggi_settimana.month - 1 if oggi_settimana.month > 1 else 12
        anno_fine = anno_inizio + (1 if mese_inizio == 12 else 0)
        mese_fine = 1 if mese_inizio == 12 else mese_inizio + 1
        inizio_mese_personalizzato = date(anno_inizio, mese_inizio, giorno_inizio)
        fine_mese_personalizzato = date(anno_fine, mese_fine, giorno_inizio - 1)
        note_mese = df.loc[
            (date_note >= inizio_mese_personalizzato) &
            (date_note <= fine_mese_personalizzato) &
            (date_note <= oggi_settimana)
        ]
        importo_mese = float(note_mese["Precio Total (Bs.)"].sum())
        importo_mese_fmt = f"{importo_mese:,.0f}".replace(",", ".")
        with st.container(key=f"nr_tabla_{sede.lower()}"):
            with st.expander(
                f"{display.upper()} · {conteggio_settimana} registros · {importo_settimana_fmt} Bs."
                f" / MES {importo_mese_fmt} Bs.",
                expanded=False,
            ):
                st.caption(f"PLANILLA DE VENTAS · {display.upper()}")
                # Settimana precedente completa: lunedì–sabato, anche se oggi è mercoledì.
                lunedi_precedente = lunedi_settimana - timedelta(days=7)
                sabato_precedente = lunedi_precedente + timedelta(days=5)
                date_prev = df["Fecha"].dt.date
                df_prev = df.loc[(date_prev >= lunedi_precedente) &
                                 (date_prev <= sabato_precedente)].copy()
                # Usa il dataset completo per includere descrizione e valori unitari.
                export_dates = all_sales["Fecha"].dt.date
                export_rows = all_sales.loc[
                    (all_sales["_sede"] == sede) &
                    (export_dates >= lunedi_precedente) &
                    (export_dates <= sabato_precedente), DATA_COLS
                ].copy().sort_values(["Fecha", "Nro Nota"], kind="stable")
                st.download_button(
                    label=f"📥 EXCEL SEMANA ANTERIOR · {lunedi_precedente:%d/%m}–{sabato_precedente:%d/%m/%Y}",
                    data=_excel_semana_anterior(export_rows, sede, lunedi_precedente, sabato_precedente),
                    file_name=f"VENTAS_{display.upper()}_{lunedi_precedente:%Y%m%d}_{sabato_precedente:%Y%m%d}.xlsx",
                    mime="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
                    key=f"excel_anterior_{sede}",
                    use_container_width=True,
                )
                if df.empty:
                    st.info("No hay notas registradas.")
                else:
                    render_mobile_sales_table(df, sede)
    render_separator_visual(TOTALS_IMAGE_URI, "Filtros de datos")
    render_section("2 · FILTROS DE DATOS", "Ventas por fecha y producto", TOTALS_IMAGE_URI, theme="ambar")
    with st.container(key="nr_ventas_fecha"):
        with st.expander("2 · VENTAS POR FECHA Y PRODUCTO", expanded=False):
            if all_sales.empty:
                default_start=default_end=date.today()
            else:
                valid_dates=all_sales["Fecha"].dropna()
                default_start=valid_dates.min().date() if not valid_dates.empty else date.today()
                default_end=max(date.today(),valid_dates.max().date()) if not valid_dates.empty else date.today()
            c1,c2=st.columns(2)
            with c1: start_date=st.date_input("Desde",value=default_start,format="DD/MM/YYYY")
            with c2: end_date=st.date_input("Hasta",value=default_end,format="DD/MM/YYYY")
            if start_date>end_date:
                st.warning("La fecha inicial debe ser anterior o igual a la final.");st.stop()
            mask=(all_sales["Fecha"].dt.date>=start_date)&(all_sales["Fecha"].dt.date<=end_date)
            # La visualizzazione delle tabelle resta limitata a Yines e Laura.
            selected=all_sales.loc[mask & all_sales["_sede"].isin(SEDES_NOTAS_VISITANTE)].copy()

            # Il filtro riguarda SOLO i calcoli del riepilogo, non nasconde le due tabelle.
            SCOPE_OPTIONS = {
                "TOTAL NUEVOS RUMBOS": ("SANTACRUZ", "TARIJA"),
                "YINES": ("SANTACRUZ",),
                "LAURA": ("TARIJA",),
            }
            scope_label = st.selectbox(
                "Calcular ventas de",
                options=list(SCOPE_OPTIONS),
                index=0,
                key="visitante_sede_calculo",
                help="TOTAL NUEVOS RUMBOS suma Yines y Laura. Camioncito solo figura en el depósito.",
            )
            summary_rows=selected.loc[selected["_sede"].isin(SCOPE_OPTIONS[scope_label])].copy()
            a,b=st.columns(2)
            with a: st.metric("MONTO VENDIDO (Bs.)", f'{summary_rows["Precio Total (Bs.)"].sum():,.2f} Bs.')
            with b: st.metric("CANTIDAD TOTAL VENDIDA", f'{int(summary_rows["Cantidad"].sum()):,}')
            st.caption(f"Resultado: {scope_label} · desde {start_date:%d/%m/%Y} hasta {end_date:%d/%m/%Y}. TOTAL NUEVOS RUMBOS incluye Yines y Laura.")

            # Consulta por producto: misma sede y mismas fechas del resumen.
            st.markdown("#### CANTIDAD VENDIDA POR PRODUCTO")
            product_path=Path(__file__).resolve().with_name("productos.txt")
            if product_path.exists():
                products=list(dict.fromkeys(x.strip() for x in product_path.read_text(encoding="utf-8-sig").splitlines() if x.strip() and not x.lstrip().startswith("#")))
            else:
                products=[]
            category_names={str(row.get("nombre") or "").strip() for row in category_config_rows if str(row.get("nombre") or "").strip()}
            if not category_names:
                category_names.update(c for c in products if c)
            category_names.update(str(c).strip() for c in all_sales["Categoría"].dropna() if str(c).strip())
            options_productos=sorted(category_names, key=str.casefold)
            if options_productos:
                chosen_product = st.selectbox(
                    "Seleccionar categoría / producto",
                    options=options_productos,
                    index=None,
                    placeholder="Desliza o escribe para buscar un producto…",
                    key="visitante_categoria_calculo",
                )
                if chosen_product is not None:
                    # Coincidenza senza distinzione maiuscole/minuscole o spazi esterni.
                    category_rows=summary_rows.loc[
                        summary_rows["Categoría"].astype(str).str.strip().str.casefold() == chosen_product.casefold()
                    ]
                    quantity=int(category_rows["Cantidad"].sum())
                    st.metric("UNIDADES VENDIDAS · " + chosen_product.upper(),f"{quantity:,}")
                    st.caption(f"{scope_label} · {start_date:%d/%m/%Y} – {end_date:%d/%m/%Y}")
            else:
                st.info("No hay productos disponibles.")

    render_separator_visual(VENTAS_FECHA_NUEVA_IMAGE_URI, "Tony — Nuevos Rumbos")
    render_section("3 · DEPÓSITO — STOCK POR SUCURSAL", "Existencias actuales por producto y ubicación", INVENTORY_IMAGE_URI, theme="glicine")
    # Leitura exclusiva della copia gia calcolata dal deposito56 PC.
    # Non consultare inventario/ventas per ricostruire alcuno stock qui.
    try:
        snapshot_result = (
            client(url, key)
            .table("deposito56_snapshot")
            .select("filas")
            .eq("id", 1)
            .execute()
        )
        snapshot_rows = (snapshot_result.data or [{}])[0].get("filas")
        if not isinstance(snapshot_rows, list):
            raise ValueError("La copia del deposito PC non contiene una lista di righe valida.")
        inv_df = pd.DataFrame(snapshot_rows)
        expected_columns = ["Producto", "Stock Camioncito", "Stock Tarija", "Stock Santa Cruz", "Stock Total"]
        if not set(expected_columns).issubset(inv_df.columns):
            raise ValueError("La copia del deposito PC non contiene tutte le colonne richieste.")
        # Conserva la precedente scelta di categorie VISIBILI sul telefono.
        # Non modifica le quantita gia calcolate nel PC.
        if category_config_available:
            visible_names = {
                str(row.get("nombre") or "").strip()
                for row in category_config_rows
                if row.get("visible_stock", True)
            }
            inv_df = inv_df[inv_df["Producto"].isin(visible_names)].copy()
        # Come prima: nasconde soltanto le vecchie righe Manometro/Manómetro.
        inv_df = inv_df[~inv_df["Producto"].astype(str).str.strip().isin({"Manómetro", "Manometro"})].copy()
        # Solo conversione per visualizzazione: nessuna somma o ricalcolo di stock.
        for col in expected_columns[1:]:
            inv_df[col] = pd.to_numeric(inv_df[col], errors="raise")
    except Exception as exc:
        st.error("Non è stato possibile leggere la copia del deposito PC da Supabase. "
                 "Controlla che il PC abbia pubblicato deposito56_snapshot e i permessi di lettura.")
        st.caption(str(exc))
        st.stop()

    # Vista Visitante: mostra esclusivamente categoria e i tre stock per sede,
    # più il totale. Ingressi, uscite e movimenti restano nascosti.
    STOCK_VISITANTE = ["Producto", "Stock Camioncito", "Stock Tarija", "Stock Santa Cruz", "Stock Total"]
    with st.container(key="nr_deposito"):
        with st.expander(f"DEPÓSITO · {len(inv_df)} productos · Stock total {int(inv_df['Stock Total'].sum()) if not inv_df.empty else 0}", expanded=False):
            stock_df = inv_df.reindex(columns=STOCK_VISITANTE)
            if stock_df.empty:
                st.info("No hay categorías de stock disponibles.")
            else:
                render_mobile_stock_table(stock_df)
    st.caption("🔒 Solo lectura: esta aplicación no puede crear, modificar ni eliminar registros. Datos consultados desde Supabase; caché de 60 segundos.")
